async function loadAircraft(url) {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  const data = await response.json();
  if (!Array.isArray(data.catalog?.aircraft)) throw new Error("Missing aircraft list");
  return data.catalog.aircraft;
}

const columns = ["Airbus", "Aircraft", "seats"];
